package wayland

import (
	"bytes"
	"fmt"
	"go/format"
	"strconv"
	"strings"

	"github.com/rm4n0s/errors"
)

// generatedHeader starts every generated file. The go tooling and golangci-lint
// recognize it.
const generatedHeader = "// Code generated by glutter-gen wayland from %s. DO NOT EDIT."

// uint32Arrays lists the array arguments that hold 32-bit unsigned integers, as
// "interface.message.argument" (a request or an event). The XML does not say what an array holds, so the
// generator is told. An array not listed here is []byte.
var uint32Arrays = map[string]bool{
	"wl_keyboard.enter.keys":                                    true,
	"xdg_toplevel.configure.states":                             true,
	"xdg_toplevel.wm_capabilities.capabilities":                 true,
	"zwp_tablet_pad_group_v2.buttons.buttons":                   true,
	"zwp_text_input_v3.set_available_actions.available_actions": true,
}

// generatedFile is one output file.
type generatedFile struct {
	name string
	data []byte
}

// fileName returns the name of the Go file generated from an XML file:
// "xdg-shell.xml" becomes "xdg_shell_gen.go".
func fileName(xmlFile string) string {
	base := strings.TrimSuffix(xmlFile, ".xml")
	return strings.ReplaceAll(base, "-", "_") + "_gen.go"
}

// generate writes the Go code of every protocol in r.
func generate(r *registry) ([]generatedFile, error) {
	g := &generator{r: r}
	g.findGenericBind()
	var files []generatedFile
	for _, p := range r.protocols {
		data, err := g.protocol(p)
		if err != nil {
			return nil, err
		}
		files = append(files, generatedFile{name: fileName(p.file), data: data})
	}
	return files, nil
}

type generator struct {
	r   *registry
	buf bytes.Buffer
	// bind is the request with a new_id argument that has no interface
	// (wl_registry.bind), for which every interface gets a typed binder.
	bindOwner *iface
	bindReq   *message
}

func (g *generator) p(format string, args ...any) {
	fmt.Fprintf(&g.buf, format, args...)
	g.buf.WriteByte('\n')
}

// findGenericBind finds the request that binds globals.
func (g *generator) findGenericBind() {
	for _, p := range g.r.protocols {
		for _, i := range p.Interfaces {
			for _, m := range i.Requests {
				if genericNewID(m) != nil && g.bindReq == nil {
					g.bindOwner, g.bindReq = i, m
				}
			}
		}
	}
}

// genericNewID returns the new_id argument of m that names no interface.
func genericNewID(m *message) *arg {
	for _, a := range m.Args {
		if a.Type == typeNewID && a.Interface == "" {
			return a
		}
	}
	return nil
}

// typedNewID returns the new_id argument of m that names an interface.
func typedNewID(m *message) *arg {
	for _, a := range m.Args {
		if a.Type == typeNewID && a.Interface != "" {
			return a
		}
	}
	return nil
}

// hasEvents reports whether the generated type installs the shared dispatcher.
// libwayland handles the events of wl_display itself.
func hasEvents(i *iface) bool {
	return len(i.Events) > 0 && i.Name != "wl_display"
}

func (g *generator) protocol(p *protocol) ([]byte, error) {
	g.buf.Reset()
	g.p(generatedHeader, p.file)
	g.p("//")
	for _, line := range strings.Split(strings.TrimSpace(p.Copyright), "\n") {
		g.p("// %s", strings.TrimSpace(line))
	}
	g.p("")
	g.p("package wl")
	for _, i := range p.Interfaces {
		g.iface(i)
	}
	src, err := format.Source(g.buf.Bytes())
	if err != nil {
		return nil, errors.NewErr("WaylandGenerateFailed", err).SetMetadata("file", p.file, "source", g.buf.String())
	}
	return src, nil
}

func (g *generator) iface(i *iface) {
	name := goName(i.Name)
	g.p("")
	g.p("// %s: %s", name, comment(i.Description.Summary))
	g.p("type %s struct {", name)
	g.p("\tProxy")
	if hasEvents(i) {
		g.p("\tevents *%sEvents", name)
	}
	g.p("}")
	g.p("")
	g.p("// %sInterface describes %s, up to version %d.", name, i.Name, i.Version)
	g.p("var %sInterface = newInterface(%q, %d)", name, i.Name, i.Version)
	g.tables(i)
	g.p("")
	g.p("func new%s(c *Conn, proxy uintptr) *%s {", name, name)
	g.p("\tself := new(%s)", name)
	g.p("\tc.register(self, proxy, %t)", hasEvents(i))
	g.p("\treturn self")
	g.p("}")
	g.p("")
	g.p("// Ptr returns the wl_proxy pointer, or 0 for a nil %s.", name)
	g.p("func (self *%s) Ptr() uintptr {", name)
	g.p("\tif self == nil {")
	g.p("\t\treturn 0")
	g.p("\t}")
	g.p("\treturn self.ptr")
	g.p("}")
	if g.bindReq != nil && i != g.bindOwner && i.Name != "wl_display" {
		g.binder(i)
	}
	for _, e := range i.Enums {
		g.enum(i, e)
	}
	g.events(i)
	for op, m := range i.Requests {
		g.request(i, op, m)
	}
}

// signature returns the wl_message signature of m and the interface of each
// argument slot.
func (g *generator) signature(m *message) (sig string, types []string) {
	var b strings.Builder
	if m.Since > 1 {
		b.WriteString(strconv.Itoa(m.Since))
	}
	for _, a := range m.Args {
		switch a.Type {
		case typeNewID:
			if a.Interface == "" {
				// A new_id without an interface carries the interface name and
				// version too.
				b.WriteString("su")
				types = append(types, "nil", "nil")
			}
		}
		if a.AllowNull {
			b.WriteByte('?')
		}
		b.WriteByte(map[string]byte{
			typeInt: 'i', typeUint: 'u', typeFixed: 'f', typeString: 's',
			typeObject: 'o', typeNewID: 'n', typeArray: 'a', typeFD: 'h',
		}[a.Type])
		if (a.Type == typeObject || a.Type == typeNewID) && a.Interface != "" {
			types = append(types, goName(a.Interface)+"Interface")
		} else {
			types = append(types, "nil")
		}
	}
	return b.String(), types
}

// tables emits the init function that fills the interface tables.
func (g *generator) tables(i *iface) {
	name := goName(i.Name)
	list := func(msgs []*message) {
		if len(msgs) == 0 {
			g.p("\t\tnil,")
			return
		}
		g.p("\t\t[]message{")
		for _, m := range msgs {
			sig, types := g.signature(m)
			g.p("\t\t\t{%q, %q, []*Interface{%s}},", m.Name, sig, strings.Join(types, ", "))
		}
		g.p("\t\t},")
	}
	g.p("")
	g.p("func init() {")
	g.p("\t%sInterface.setMessages(", name)
	list(i.Requests)
	list(i.Events)
	g.p("\t)")
	g.p("}")
}

// binder emits BindX, which binds a global of interface i through the registry.
func (g *generator) binder(i *iface) {
	name := goName(i.Name)
	owner := goName(g.bindOwner.Name)
	raw := goName(g.bindReq.Name) + "Raw"
	g.p("")
	g.p("// Bind%s binds the global %s with the given registry name and version.", name, i.Name)
	g.p("func Bind%s(registry *%s, name, version uint32) *%s {", name, owner, name)
	g.p("\tproxy := registry.%s(name, %sInterface, version)", raw, name)
	g.p("\tif proxy == 0 {")
	g.p("\t\treturn nil")
	g.p("\t}")
	g.p("\treturn new%s(registry.conn, proxy)", name)
	g.p("}")
}

func (g *generator) enum(i *iface, e *enum) {
	typeName := goName(i.Name + "_" + e.Name)
	g.p("")
	g.p("// %s: %s", typeName, comment(e.Description.Summary))
	g.p("type %s uint32", typeName)
	g.p("")
	g.p("const (")
	for _, en := range e.Entries {
		if en.Summary != "" {
			g.p("\t// %s%s: %s", typeName, goName(en.Name), comment(en.Summary))
		}
		g.p("\t%s%s %s = %s", typeName, goName(en.Name), typeName, en.Value)
	}
	g.p(")")
}

// enumType returns the Go type name of the enum that argument a refers to.
func (g *generator) enumType(from *iface, a *arg) string {
	owner, e, _ := g.r.findEnum(from, a.Enum)
	return goName(owner.Name + "_" + e.Name)
}

// goType returns the Go type of an argument, as a parameter of a request or an
// event callback.
func (g *generator) goType(from *iface, message string, a *arg) string {
	switch a.Type {
	case typeInt:
		if a.Enum != "" {
			return g.enumType(from, a)
		}
		return "int32"
	case typeUint:
		if a.Enum != "" {
			return g.enumType(from, a)
		}
		return "uint32"
	case typeFixed:
		return "float64"
	case typeString:
		return "string"
	case typeObject, typeNewID:
		if a.Interface == "" {
			return "Object"
		}
		return "*" + goName(a.Interface)
	case typeArray:
		if uint32Arrays[from.Name+"."+message+"."+a.Name] {
			return "[]uint32"
		}
		return "[]byte"
	default: // typeFD
		return "int"
	}
}

func (g *generator) events(i *iface) {
	name := goName(i.Name)
	if !hasEvents(i) {
		g.p("")
		g.p("func (self *%s) dispatch(opcode uint32, a eventArgs) {}", name)
		return
	}
	g.p("")
	g.p("// %sEvents holds the callbacks for the events of %s. A nil callback ignores the event.", name, i.Name)
	g.p("type %sEvents struct {", name)
	for _, m := range i.Events {
		var params []string
		for _, a := range m.Args {
			params = append(params, argName(a.Name)+" "+g.goType(i, m.Name, a))
		}
		g.p("\t// On%s: %s", goName(m.Name), comment(m.Description.Summary))
		g.p("\tOn%s func(%s)", goName(m.Name), strings.Join(params, ", "))
	}
	g.p("}")
	g.p("")
	g.p("// SetEvents sets the callbacks for the events of the object. It replaces the previous ones.")
	g.p("func (self *%s) SetEvents(events *%sEvents) { self.events = events }", name, name)
	g.p("")
	g.p("func (self *%s) dispatch(opcode uint32, a eventArgs) {", name)
	g.p("\tev := self.events")
	g.p("\tswitch opcode {")
	for op, m := range i.Events {
		g.p("\tcase %d: // %s", op, m.Name)
		var vals []string
		for k, a := range m.Args {
			switch {
			case a.Type == typeNewID && a.Interface != "":
				// libwayland has already created the proxy, so wrap it even
				// when nobody listens.
				g.p("\t\targ%d := new%s(self.conn, a.object(%d))", k, goName(a.Interface), k)
				vals = append(vals, fmt.Sprintf("arg%d", k))
			default:
				vals = append(vals, g.decode(i, m, k, a))
			}
		}
		field := "On" + goName(m.Name)
		g.p("\t\tif ev == nil || ev.%s == nil {", field)
		g.p("\t\t\treturn")
		g.p("\t\t}")
		g.p("\t\tev.%s(%s)", field, strings.Join(vals, ", "))
	}
	g.p("\t}")
	g.p("}")
}

// decode returns the expression that reads argument k of event m.
func (g *generator) decode(from *iface, m *message, k int, a *arg) string {
	switch a.Type {
	case typeInt:
		if a.Enum != "" {
			return fmt.Sprintf("%s(a.int(%d))", g.enumType(from, a), k)
		}
		return fmt.Sprintf("a.int(%d)", k)
	case typeUint:
		if a.Enum != "" {
			return fmt.Sprintf("%s(a.uint(%d))", g.enumType(from, a), k)
		}
		return fmt.Sprintf("a.uint(%d)", k)
	case typeFixed:
		return fmt.Sprintf("a.fixed(%d)", k)
	case typeString:
		return fmt.Sprintf("a.str(%d)", k)
	case typeObject:
		if a.Interface == "" {
			return fmt.Sprintf("lookup[Object](self.conn, a.object(%d))", k)
		}
		return fmt.Sprintf("lookup[*%s](self.conn, a.object(%d))", goName(a.Interface), k)
	case typeArray:
		if uint32Arrays[from.Name+"."+m.Name+"."+a.Name] {
			return fmt.Sprintf("a.uint32s(%d)", k)
		}
		return fmt.Sprintf("a.array(%d)", k)
	default: // typeFD
		return fmt.Sprintf("int(a.fd(%d))", k)
	}
}

// request emits the method that sends request number opcode of interface i.
func (g *generator) request(i *iface, opcode int, m *message) {
	name := goName(i.Name)
	method := goName(m.Name)
	generic := genericNewID(m)
	typed := typedNewID(m)

	var params []string
	slots := 0
	for _, a := range m.Args {
		switch a {
		case typed:
			slots++
		case generic:
			params = append(params, "iface *Interface", "version uint32")
			slots += 3
		default:
			params = append(params, argName(a.Name)+" "+g.goType(i, m.Name, a))
			slots++
		}
	}
	ret, retDoc := "", ""
	switch {
	case typed != nil:
		ret = " *" + goName(typed.Interface)
	case generic != nil:
		method += "Raw"
		ret = " uintptr"
		retDoc = " It returns the wl_proxy of the new object, which the typed Bind functions wrap."
	}

	g.p("")
	doc := fmt.Sprintf("%s: %s.%s", method, strings.TrimSuffix(comment(m.Description.Summary), "."), retDoc)
	if m.Type == "destructor" {
		doc += " It destroys the object."
	}
	if m.Since > 1 {
		doc += fmt.Sprintf(" Since version %d.", m.Since)
	}
	g.p("// %s", doc)
	g.p("func (self *%s) %s(%s)%s {", name, method, strings.Join(params, ", "), ret)
	g.p("\targv := newArgs(%d)", slots)
	g.p("\tdefer argv.free()")
	slot := 0
	for _, a := range m.Args {
		switch a {
		case typed:
			// The new object's ID is filled in by libwayland.
		case generic:
			g.p("\targv.setString(%d, iface.Name)", slot)
			g.p("\targv.setUint(%d, version)", slot+1)
			slot += 2
		default:
			g.p("\t%s", g.encode(i, m, slot, a))
		}
		slot++
	}
	flags := "0"
	if m.Type == "destructor" {
		flags = "flagDestroy"
	}
	switch {
	case typed != nil:
		g.p("\tproxy := self.marshal(%d, %sInterface, self.version, %s, argv)", opcode, goName(typed.Interface), flags)
		g.p("\tif proxy == 0 {")
		g.p("\t\treturn nil")
		g.p("\t}")
		g.p("\treturn new%s(self.conn, proxy)", goName(typed.Interface))
	case generic != nil:
		g.p("\treturn self.marshal(%d, iface, version, %s, argv)", opcode, flags)
	default:
		g.p("\tself.marshal(%d, nil, self.version, %s, argv)", opcode, flags)
	}
	g.p("}")
}

// encode returns the statement that stores request argument a in slot.
func (g *generator) encode(from *iface, m *message, slot int, a *arg) string {
	n := argName(a.Name)
	switch a.Type {
	case typeInt:
		if a.Enum != "" {
			return fmt.Sprintf("argv.setInt(%d, int32(%s))", slot, n)
		}
		return fmt.Sprintf("argv.setInt(%d, %s)", slot, n)
	case typeUint:
		if a.Enum != "" {
			return fmt.Sprintf("argv.setUint(%d, uint32(%s))", slot, n)
		}
		return fmt.Sprintf("argv.setUint(%d, %s)", slot, n)
	case typeFixed:
		return fmt.Sprintf("argv.setFixed(%d, %s)", slot, n)
	case typeString:
		if a.AllowNull {
			return fmt.Sprintf("argv.setNullableString(%d, %s)", slot, n)
		}
		return fmt.Sprintf("argv.setString(%d, %s)", slot, n)
	case typeObject:
		if a.Interface == "" {
			return fmt.Sprintf("if %s != nil {\n\t\targv.setObject(%d, %s.Ptr())\n\t}", n, slot, n)
		}
		return fmt.Sprintf("argv.setObject(%d, %s.Ptr())", slot, n)
	case typeArray:
		if uint32Arrays[from.Name+"."+m.Name+"."+a.Name] {
			return fmt.Sprintf("argv.setArray(%d, uint32sToBytes(%s))", slot, n)
		}
		return fmt.Sprintf("argv.setArray(%d, %s)", slot, n)
	default: // typeFD
		return fmt.Sprintf("argv.setFD(%d, int32(%s))", slot, n)
	}
}
